def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my = history[-1][0]
    last_opp = history[-1][1]

    opp_c = 0
    my_c = 0
    recent3_opp_c = 0
    recent5_opp_c = 0
    recent10_opp_c = 0

    for i in range(n):
        a = history[i][0]
        b = history[i][1]

        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1

        if i >= n - 3 and b == 'C':
            recent3_opp_c += 1
        if i >= n - 5 and b == 'C':
            recent5_opp_c += 1
        if i >= n - 10 and b == 'C':
            recent10_opp_c += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    after_d_total = 0
    after_d_c = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            after_d_total += 1
            if history[i + 1][1] == 'C':
                after_d_c += 1

    if opp_c == 0:
        if n <= 3:
            return 'C'
        return 'D'

    mostly_cooperative = opp_c * 10 >= n * 7

    if last_opp == 'C':
        if (
            after_d_total >= 1 and
            after_d_c == after_d_total and
            recent10_opp_c >= 6 and
            opp_c * 10 >= n * 7
        ):
            return 'D'

        if (
            mostly_cooperative and
            opp_c == n and
            my_c == n and
            n < 95 and
            rng.random() < 0.01
        ):
            return 'D'

        return 'C'

    if mostly_cooperative:
        if opp_d_streak >= 4 and recent5_opp_c == 0:
            return 'D'
        return 'C'

    if last_my == 'D' and opp_d_streak >= 3 and recent5_opp_c >= 1:
        return 'C'

    if opp_d_streak >= 2:
        return 'D'

    if recent3_opp_c >= 1:
        return 'C'

    if recent10_opp_c >= 2:
        return 'C'

    return 'D'
